/* Generated by build_narr.py: AOI_NARR[hash of English caption] = [clip in audio/narr/, what Aoi says]. */
var AOI_NARR = {"c59f5d39":["fa3b68dd77f1.mp3","標準語、大阪弁、京都弁。それから、日本のいろんな地方の言葉をめぐる旅だよ！"],"e5344932":["d64a291a6a71.mp3","日本にはたくさんの方言があるの。標準語は東京の言葉がもとになっていて、テレビや学校、このアプリでも使ってる。誰にでも通じるよ。"],"28c8ec88":["a6ba30b1b418.mp3","一番有名なのは関西弁。大阪、京都、神戸の言葉だね。メロディーが違って、アクセントが逆になる言葉もあるんだ。ありがとうは「おおきに」！"],"d9f98784":["46579df3fdd4.mp3","大阪弁は元気いっぱいで、お笑いで有名！「ほんま」は本当、「あかん」はダメ。そして、ツッコミといえば「なんでやねん！」"],"58e2a5bc":["2a2176aced11.mp3","大阪の「なんでやねん」。英語だと、why on earth、みたいな感じ。漫才の定番のツッコミだよ。"],"824c8aa8":["1d25ee38162b.mp3","関西では、「ない」の代わりに「へん」を使うの。「行かない」は「行かへん」になるよ。"],"70cf5cf4":["86e743be5a94.mp3","京都弁はやわらかくて丁寧。有名なのが「はる」。やさしく敬意を表す言い方で、「来はる」は「来る」の丁寧な形だよ。"],"f8a757fb":["ab7410cc8da7.mp3","京都の昔ながらのお迎えの言葉。老舗のお店やお茶屋さんで聞けるよ。「おいでやす」。"],"8260214d":["bf6946bc9da1.mp3","福岡には博多弁があるの。この甘いセリフが有名だよ。「好いとーよ」。好きだよ、っていう意味！"],"0e969a71":["0869df436dcc.mp3","広島では、「だから」の意味で「じゃけえ」って言うよ。"],"1ff33d2d":["16c2cf671586.mp3","名古屋では、「とても」のことを「でら」って言うの。「でらうまい」は、すごくおいしい！"],"aeb4ec0f":["34e231a6689c.mp3","北の東北地方では、「べ」をよく使うよ。「行くべ」は、行こう、っていう意味。"],"73e377e5":["6d1397ab1400.mp3","沖縄には、琉球の言葉があるの。有名な歓迎の言葉は「めんそーれ」！"],"68c87e11":["65f77efb8cac.mp3","私はぜんぶ標準のメロディーで読んでいるから、本当のアクセントは地元の人に聞いてみてね。それに、標準語ならどこでも通じるから安心して！"],"ac122ede":["01ff7fcb8540.mp3","語順、文の最後に来る動詞、それから言葉を省略すること。"],"6d2db954":["2bcca4ffd7af.mp3","日本語では、動詞が最後に来るの。基本の順番は、話題、それから詳しいこと、最後に動詞だよ。"],"a1ec5788":["b3ce6d455a2a.mp3","助詞っていう小さな言葉が、単語のあとについて、その役割を決めるの。ここでは「に」が、行き先を表しているよ。"],"8ea50358":["0106e87fbbf8.mp3","誰のことか分かっているときは、省略していいの。日本語では「私」や「あなた」をしょっちゅう省くんだ。"],"6531ee30":["db26c9c4629f.mp3","時間や場所も、動詞の前に来るよ。よくある順番は、話題、時間、場所、目的語、そして動詞。"],"00ca54e0":["0f06ccccbabe.mp3","動詞の終わりで時制が分かるの。「食べます」は今かこれから、「食べました」は過去。くわしくは「動詞と時制」でね。"],"d16d5565":["3397b5623802.mp3","「XはYです」で、XはYだ、と言えるよ。最後の「です」は丁寧な言い方なんだ。"],"daa083ea":["a3ae9f09e024.mp3","単語のあとについて、その単語の役割を表す小さな言葉、助詞だよ。"],"642507be":["a604155ea7e8.mp3","「は」は話題を表すの。文が何についての話かを示すんだ。書くときは「は」だけど、発音は「わ」だよ。"],"86eec30e":["13f1de0114e4.mp3","「を」は目的語、つまり動作を受けるものを表すよ。発音は「お」。"],"b9158ec1":["dce21fe121e2.mp3","「に」は一つの点を表すの。何かが起きる時間や、行き先だよ。"],"3cd910b2":["06b8e8cb586d.mp3","「で」は、何かをする場所や、電車で、みたいに手段を表すよ。"],"c63b4695":["bb823f8a9c7f.mp3","「へ」は方向、「〜のほうへ」っていう意味。書くときは「へ」だけど、発音は「え」。行き先を言うときは「に」とほとんど同じだよ。"],"f210104c":["4ab5946fab93.mp3","「と」は「一緒に」、それから名詞と名詞をつなぐ「and」の意味だよ。"],"72838af9":["8ec340043f65.mp3","「も」は「〜も」、tooやalsoの意味。「は」「が」「を」の代わりに使うよ。"],"ae8b1252":["decd9aaabca0.mp3","「の」は名詞と名詞をつなぐの。英語のofや、アポストロフィーsみたいにね。「私の名前」は、my name。"],"383c8071":["f455a5094ff8.mp3","「が」は主語を指して、好きなものやほしいものにも使うよ。「猫が好き」は、I like cats。"],"2c72bdcf":["0e47afab5dce.mp3","丁寧な文の最後に「か」をつけると、質問になるよ。"],"d4433582":["081b5452b541.mp3","二つの時制、丁寧な形とカジュアルな形、そして三種類の動詞。"],"a2dcbdda":["34d9ed35974b.mp3","日本語の時制は二つだけ。過去と、過去じゃないもの。同じ形で、今のこともこれからのことも言えるの。"],"6b9e065d":["2de18862d860.mp3","ここでは同じ「行きます」が、明日行く、っていう意味になるよ。「明日」があるからね。"],"4131a628":["0c39703256b2.mp3","過去にするときは、「ます」を「ました」に変えるよ。"],"37dd84c8":["fe6e801e0a84.mp3","否定にするときは、「ます」を「ません」に。過去の否定は「ませんでした」だよ。"],"2a4af7f5":["5e29cbd88d4e.mp3","カジュアルな話し方では、普通形を使うの。意味は同じで、友だちや家族と話すときに使うよ。"],"c60decc0":["d19fea70ebc7.mp3","動詞は三種類。る動詞は「る」を取って、う動詞は最後の音が変わる。そして、不規則動詞が二つあるよ。"],"c636c266":["0d42a1170b09.mp3","「ています」は、今まさにしていること、または続いている状態を表すよ。"],"fec4b0b0":["eddc1ffbedcf.mp3","何かをしたいときは、動詞の語幹に「たいです」をつけるの。"],"1095873b":["0f557e8cb163.mp3","「です」、二種類の形容詞、そしてその過去形と否定形。"],"bdadb14c":["e92a282c5170.mp3","名詞には「です」を使うよ。カジュアルだと「だ」になって、よく省略されるの。"],"2fafc479":["5c5e070a5cb4.mp3","い形容詞は「い」で終わるよ。丁寧に言うときは「です」をつけてね。"],"ccc81551":["4518fb895eda.mp3","い形容詞は、自分の語尾が変わるの。「高い」「高くない」「高かった」。「高いでした」とは言わないよ。"],"4b69f4a4":["d6b62ecea976.mp3","な形容詞は名詞と同じように、「です」や「だ」と一緒に使うよ。"],"bcda1c56":["0051a6c762ca.mp3","名詞の前では、な形容詞に「な」がつくの。「静かな町」。い形容詞はそのまま、「高い山」だよ。"],"6786555d":["240612f05c0a.mp3","例外が一つ。「いい」は、ほかの形では「よ」に変わるの。「よくない」「よかった」。"],"ec026f69":["7e84a79f64d0.mp3","「か」、何、どこ、いつ、誰。それから、答え方。"],"27a1bc4f":["6fd6d1fad136.mp3","丁寧な質問は、文の最後に「か」をつけるだけ。語順は変わらないよ。"],"e594eda4":["cb5f031bc727.mp3","「何」は what。「です」の前では「なん」って読むよ。"],"208b716f":["6d390ddce515.mp3","「どこ」は where。これはたくさん使うよ！"],"ede69551":["3ef534ddc840.mp3","「いつ」は when だよ。"],"825b5fe1":["0dbd8d5ac0bd.mp3","「誰」は who だよ。"],"c73cd2a7":["a4ad9377023f.mp3","カジュアルなときは、「か」を取って語尾を上げるか、「の」で終わるよ。"],"f8fbc7fd":["d5a3c2bc96e2.mp3","答えるときは、動詞をくり返すのが普通。「行きます」とか「行きません」。「はい」は yes だよ。"],"b1294587":["1a801d125841.mp3","してください、しませんか、しましょう。て形と、その仲間たち。"],"9eb85900":["517a8784a14a.mp3","誰かに何かをお願いするときは、て形に「ください」をつけるよ。"],"cd92032f":["d63d153bd490.mp3","る動詞のて形は、「る」を「て」に変えるだけ。"],"22d9094f":["cb481fc7f7d5.mp3","う動詞は、最後の音によって変わり方が違うの。「行く」だけは例外で、「行って」になるよ。"],"da36c8a7":["35a4bdfc6ce4.mp3","誘うときは、「ませんか」と否定の形で聞くの。英語の won't you? だね。"],"4ee09f16":["64591dba612a.mp3","「ましょう」は、let's の意味だよ。"],"f625a7a5":["e9e5b6befa37.mp3","友だち同士なら、カジュアルな「〜しよう」は「おう」か「よう」で終わるよ。"],"9180002c":["d076a3cea8a9.mp3","動詞のグループ。辞書形から、ます形へ。どの形もタップすると聞けるよ。"],"440223f4":["38863d42450f.mp3","「食べる」、to eat。る動詞だから、「る」を取って語尾をつけるよ。"],"54b63a1a":["f4504f9cf34f.mp3","「行く」、to go。う動詞だから、最後の音が変わるの。く、き、か、こ、みたいにね。"],"7b222c17":["d76bd015560f.mp3","「する」、to do。不規則動詞だから、そのまま覚えてね。「勉強する」みたいに、たくさんの動詞を作るよ。"],"0f2c9483":["eb2afc134b7c.mp3","「来る」、to come。不規則動詞で、「来」の読み方が、く、こ、き、と変わるの。"],"684154ec":["c507c840d727.mp3","て形。辞書形から、て形へ。どの形もタップすると聞けるよ。"],"b16e13e0":["bd887bd3d638.mp3","「高い」、expensive や tall の意味。い形容詞だから、自分の語尾が変わるよ。"],"ab7687ab":["7639a6b46923.mp3","「静か」、quiet。な形容詞だから、名詞みたいに「だ」や「です」を使うよ。名詞の前では「な」をつけて、「静かな町」。"],"20894bee":["e18d4edd1eeb.mp3","「学生」、student。名詞だね。名詞は「だ」や「です」を使うよ。かたい書き言葉では、否定は「ではありません」。"],"eb3de42d":["bf7e4a6a188f.mp3","左、右、まっすぐ。それから、どこにあるか聞く方法。"],"6bed9f3f":["79e3787be14a.mp3","店員さんの呼び方、注文の仕方、そしてお会計。"],"0a64e039":["7779b63ff8e5.mp3","動物たち、何をするか、そして日本語での鳴き声！"],"1d64c62f":["7d83a1f5a72f.mp3","日本で見かけたり、聞いたりする鳥たちと、その鳴き声。"],"ddb5c646":["35c091915691.mp3","虫たち、何をするか、そして夏の一番うるさい音！"],"18ead113":["37f222eecf19.mp3","種から花まで。そして、日本で愛されている植物たち。"],"916e0afd":["c9c02514c1fd.mp3","魔女、ほうき、呪文。それから、日本のお父さんお母さんが本当に使うおまじない！"],"74ce425c":["49bbc8c80320.mp3","ドレス、着物。それから、「着る」を表す三つの違う動詞。"],"a650668d":["b5e65d2e3a43.mp3","目、耳、鼻、口、歯。それぞれ何をするのかな。"],"0879591b":["8e33afc30cf7.mp3","頭からつま先まで。そして、体の中で毎日がんばっている臓器たち。"],"2813c9cc":["a67fc7546bc1.mp3","どこが痛いかを伝える言葉。薬局でも、病院でも使えるよ。"],"7d2bd9c6":["fe5787983df8.mp3","日本語での八つの惑星。それから、曜日の名前がどこから来たのか。"],"d1b3a969":["edcf7a1b1076.mp3","星の言葉、天の川、そして七夕の恋の物語。"],"9e740cc1":["4a871d41f96a.mp3","心臓の四つの部屋、動脈と静脈を、日本語で。"],"95e73679":["5bcc631a93e4.mp3","お話の時間だよ！丁寧かカジュアルか、標準語か大阪弁か京都弁か、選んでね。どの行でも切り替えられるよ。今日は月から来たお姫さま、日本で一番古いお話の一つ、かぐや姫。読んだ行は下に積み重なっていくから、いつでも上にスクロールして見返してね。"],"ffce48eb":["d892257a9b94.mp3","お話の時間だよ！丁寧かカジュアルか、標準語か大阪弁か京都弁か、選んでね。どの行でも切り替えられるよ。今日はヨーロッパの昔話を、やさしい日本語で。顔の言葉がたくさん出てくるよ。読んだ行は積み重なっていくから、いつでも上にスクロールして見返してね。"],"6bb20658":["5b130426cdcd.mp3","お話の時間だよ！丁寧かカジュアルか、標準語か大阪弁か京都弁か、選んでね。どの行でも切り替えられるよ。今日は桃から生まれた男の子と、三匹の動物の仲間たちのお話。読んだ行は積み重なっていくから、いつでも上にスクロールして見返してね。"],"6a21120e":["884b78a0f98f.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。これは日本の子どもたちが学校で習う歌。どの番も同じ形のくり返しだから、「が」と「に」の練習にぴったり！読んだ行は積み重なっていくから、いつでも見返してね。"],"7d93d2ea":["412bb7b3895e.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。子どもがハトに豆をまいてあげる歌。カジュアルな毎日の文法がいっぱいだよ。読んだ行は積み重なっていくから、いつでも見返してね。"],"3aee7213":["fd083ae4709c.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。お母さんカラスが鳴いているのは、山のおうちで子どもたちが待っているから。読んだ行は積み重なっていくから、いつでも見返してね。"],"f6b25e8a":["9a9259428d17.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。ウサギが、のろまだねってカメをからかうの。競走の結末は、知ってるよね！読んだ行は積み重なっていくから、いつでも見返してね。"],"8529f102":["d104d03147f0.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。大人になった人が、小さいころ誰かに背負われて、夕焼けの中で見た赤とんぼを思い出す歌。読んだ行は積み重なっていくから、いつでも見返してね。"],"d34a420d":["e8d5f6146561.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。昔の日本語で書かれているから、言葉が昔どうだったかを、ちょっとのぞけるよ。読んだ行は積み重なっていくから、いつでも見返してね。"],"e8cf5132":["33eee7e1647d.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。これは昔の言葉で書かれた、もとの歌詞だよ。「弥生」は三月の昔の呼び名で、桜が咲くころなんだ。読んだ行は積み重なっていくから、いつでも見返してね。"],"1f45dcea":["4ab2ef9c074f.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。一人が真ん中で目をかくしてしゃがんで、ほかの子たちが歌いながらまわりを歩くの。歌が終わったら、真後ろにいるのは誰か当てるんだよ。読んだ行は積み重なっていくから、いつでも見返してね。"],"62f443a2":["10313d5c514c.mp3","一緒に歌を読もう。一行ずつ私が読んで、そのあと今の言い方も聞けるよ。丁寧かカジュアルか、標準語、大阪弁、京都弁。動きもやってみてね。手をにぎって「結んで」、手を開いて「開いて」、手をたたいて「手を打って」、最後に手を「上に」！読んだ行は積み重なっていくから、いつでも見返してね。"],"7311336f":["96ead436a24f.mp3","俳句の時間だよ！一句ずつ読んで、そのあと今の言葉でも言うね。好きな言い方を選んでね。俳句は五、七、五の音でできていて、季節を表す「季語」が一つ入るの。この六つは、日本でとても有名な句だよ。読んだ句は積み重なっていくから、いつでも見返してね。"],"03ac3e97":["703872764959.mp3","五本の線、四つの間、そしてそこに住んでいる音符たち。五線の上の音符をタップすると、音が聞けるよ。"],"8f093959":["86aff2fc21b4.mp3","楽譜は五線に書くの。五本の線と、四つの間。音符が高いところにあるほど、高い音になるよ。"],"21553fb7":["429b24dd0db5.mp3","このくるっとした記号が、ト音記号。下から二本目の線に巻きついていて、その線が G、つまりソの音なんだ。"],"25220b8e":["cb85f2b0091a.mp3","線の音は、下から E、G、B、D、F。英語では、Every Good Boy Does Fine、って覚えるんだよ。"],"e2a8dd71":["dd694b3f18f9.mp3","間の音は、言葉になるの。F、A、C、E。FACE、顔だね！"],"bd089aa0":["3b2cfd48e087.mp3","真ん中のドは、五線の下にある短い線、加線の上にあるよ。ピアノの真ん中あたりの音なんだ。"],"65e3b710":["9e2e086967b0.mp3","ドからドまで、日本のドレミ、それからシャープとフラット。五線の上の音符をタップすると聞けるよ。"],"ddab32c1":["f572ae75b95e.mp3","音の名前は、七つのアルファベット。C、D、E、F、G、A、B。そしてまた、一オクターブ上の C から始まるよ。"],"14c932d0":["e30ba7eaefdd.mp3","日本の学校の音楽では、ドレミを使うよね。ド、レ、ミ、ファ、ソ、ラ、シ、ド。一緒に歌おう！"],"b133101b":["dd55e87b5a34.mp3","日本の調の名前は、昔のかなを使うの。C、D、E、F、G、A、B は、ハ、ニ、ホ、ヘ、ト、イ、ロ。だから C major は、ハ長調だよ。"],"f503b66e":["9bb29bd272bb.mp3","シャープは、音を半音上げる記号。聞いてみて。ファ、そしてファのシャープ。"],"70094c8e":["4aa91b29457d.mp3","フラットは、音を半音下げる記号。ピアノでは、シャープやフラットはだいたい黒い鍵盤だよ。"],"ab7bd71b":["b9a199429c02.mp3","全音符、二分音符、四分音符、八分音符、付点、そして休符。五線の上の音符をタップすると聞けるよ。"],"54f0d105":["f1496889cd51.mp3","全音符は、棒のない白い丸。長さは四拍だよ。"],"44f3f165":["650b415f4c13.mp3","二分音符は、棒のついた白い丸。一つで二拍。"],"6f12f7cc":["c3262a19246d.mp3","四分音符は、黒くぬった丸に棒。一つで一拍だよ。"],"46ca7a28":["877026a17481.mp3","八分音符には、小さな旗がついてるの。半拍だから、一拍に二つ入るよ。"],"efc16489":["67ad1604c1eb.mp3","付点は、その音符の半分の長さを足すの。付点二分音符は三拍だよ。"],"b2119fe4":["71f37a77db82.mp3","休符は、同じ長さのお休み。ここでは、音、休み、音、休み。"],"93f849a2":["49ef21734eb2.mp3","小節線、拍子記号、そしてはじめてのメロディー。五線の上の音符をタップすると聞けるよ。"],"9b04073a":["c1984f27d40f.mp3","小節線は、音楽を小節に区切る線。最初の数字が拍子記号で、四分の四は、一小節に四分音符が四つ、っていう意味だよ。"],"1e7b00b2":["7ed2a4deaa33.mp3","四分の三は、一小節に三拍。ワルツみたいに、イチ、ニ、サン、イチ、ニ、サン。"],"7e1edfd0":["211b2a081c4d.mp3","本物の曲を読んでみよう。日本のきらきら星の始まりだよ。私がハミングするから、音符を一つずつ追ってね。"],"c15b4063":["9a153041a149.mp3","次の行だよ。だんだん下がっていくのに気づいたかな。ファ、ミ、レ、ド。"],"51eaa97b":["4c54ffce6894.mp3","これで楽譜が読めたね！次は日本の歌もやってみて。さくらさくら、ちょうちょう、ほかにもあるよ。音符をタップすると聞けるよ。"],"3321c01a":["ffe97e162605.mp3","やさしいコードが八つあれば、何百曲も弾けちゃうよ。図は弦を表していて、左が一番低いEの弦。どこを押さえるかも書いてあるよ。図をタップすると、ジャランと鳴るよ。"],"d7835187":["8120ad8fc6f8.mp3","C メジャー。明るくて、楽しいコード。一番低いEの弦は弾かないでね。形は、バツ、3、2、0、1、0。"],"7ff4a23c":["e3777ffc5a3d.mp3","G メジャー。大きくて、広がる響き。六本ぜんぶ鳴らすよ。形は、3、2、0、0、0、3。"],"df380a7e":["6bfb171edd06.mp3","D メジャー。上の四本だけで、小さな三角の形。形は、バツ、バツ、0、2、3、2。"],"e84ec781":["99bfd5ac34af.mp3","E マイナー。指はたった二本！マイナーコードは、やわらかくて少しさみしい響きだよ。形は、0、2、2、0、0、0。"],"33befa33":["4476ae75d9f3.mp3","A マイナー。E メジャーと同じ形を、弦一本ぶんずらしたものだよ。形は、バツ、0、2、2、1、0。"],"5339b50b":["3720b39d7f26.mp3","E メジャー。Em に、G の弦の指を一本足した形。形は、0、2、2、1、0、0。"],"c0f0daf4":["41ce4d1e25be.mp3","D マイナー。上の四本で、やさしくて切ない響き。さくらさくらでも使うよ。形は、バツ、バツ、0、2、3、1。"],"c44c9b51":["1f01f2c4b4ee.mp3","F メジャーセブン。むずかしいセーハがいる F の、かんたんな代わりだよ。夢みたいな響き。形は、バツ、バツ、3、2、1、0。"],"7e010c70":["666368ac5b1e.mp3","C、G、Am、Em を切り替えてみて。数えきれないほどのポップスで使われているコードだよ。タップすると聞けるよ。"],"1889632f":["a63b30fb2faa.mp3","コードの図鑑だよ。どの図もタップすると聞けるよ。まずはオープンコード、それからセブンス、セーハコード、そして J-rock のパワーコード。"],"34c37925":["ecea93b99c83.mp3","オープンコード。一つずつタップして鳴らしてみてね。"],"4a67ea4d":["c9d5ad03dad5.mp3","セブンス。J-pop らしい色だよ。一つずつタップして鳴らしてみてね。"],"87ddedbb":["0f7deb1cc38d.mp3","セーハコード。一つずつタップして鳴らしてみてね。"],"dfa3e7bc":["e5bcfc3fe95b.mp3","パワーコード、J-rock の音！一つずつタップして鳴らしてみてね。"],"9801db47":["dc76197426a7.mp3","指一本で六本の弦をぜんぶ押さえる。これが、ネックのどこでもコードを弾くカギだよ。図をタップすると聞けるよ。"],"c4812810":["3e89f05f8570.mp3","セーハコードは、人差し指をカポみたいに使って、一つのフレットの弦をぜんぶ押さえるの。図の中の棒がそれを表しているよ。"],"f7dacb87":["d0939cebd39b.mp3","F は、最初に出会う有名なセーハコード。人差し指を少しだけ骨のある側に転がして、親指はネックの裏に。フレットのすぐ近くを押さえるのがコツだよ。"],"9219501b":["cd752771c199.mp3","Bm は、Aの弦の2フレットからのセーハ。一番低いEの弦は弾かないでね。"],"aac9faff":["838d88a7d37f.mp3","ここが魔法のところ。同じセーハの形をネックの上にずらすと、別のコードになるの。F の形を3フレットに持っていくと G、5フレットなら A だよ。"],"82803ad7":["1f2e444f1208.mp3","最初はセーハがビビっても大丈夫、普通のことだよ。毎日数分練習すれば、力がついてくるからね。それまでは、Fmaj7 が F のやさしい代わりになってくれるよ。"],"d3ab6018":["035f7b08e0f9.mp3","音は二つか三つ、大きくてパンチがある。これが J-rock の音！図をタップすると聞けるよ。"],"9525346e":["2b51ed9d7bbb.mp3","パワーコードは、ルート音とその五度の音だけ。上にオクターブの音を足すことも多いよ。E5 みたいに、5 をつけて書くの。"],"5396c37b":["c382272d4821.mp3","三度の音がないから、メジャーでもマイナーでもない。だから、ひずみを強くかけても音がにごらないの。ロックバンドが大好きな理由だよ。"],"9b4405ba":["1ca95164623c.mp3","この形は、どこへでも動かせるよ。ルートは低いEの弦かAの弦、五度はその隣の弦の、二フレット上。"],"c6ced5b9":["a502d2d0f973.mp3","E5、G5、A5 と弾いてみて。この形をずらす動きは、数えきれないロックのリフに出てくるよ。"],"cd2d1cdf":["71998e719e5f.mp3","J-rock らしい疾走感を出すなら、速いダウンストロークで弾いてみて。手のひらをブリッジの近くの弦に軽くのせるの。これがパームミュートだよ。"],"1f86ee76":["570c0df8c97a.mp3","キック、スネア、ハイハット。それから、ビートの数え方。"],"e0974c4a":["8d3f067de01d.mp3","キックドラムは、足で踏む大きくて低いドンという音。曲の心臓の音みたいなものだよ。"],"0e4c6606":["27b218bd6db6.mp3","スネアは、真ん中で鳴るパシッという鋭い音。たいてい二拍目と四拍目に入るよ。これがバックビート。"],"1d43858b":["06cd66cab9a9.mp3","ハイハットは、チッチッとリズムを刻むシンバル。たいてい八分音符ごとに鳴らすよ。"],"18ccc7a4":["0d9c0afc7482.mp3","ドラマーは十六分音符を、ワン・エ・アン・ダ、ツー・エ・アン・ダ、って数えるの。グリッドの四角一つが、その一つ分だよ。"],"05d354f8":["a375d5c5ef31.mp3","ぜんぶ合わせると、8ビート！ロックや J-pop の基本のリズムだよ。次は自分で叩いてみよう！"],"ae08cbb8":["bd0e789b0258.mp3","四本の弦、ルート音、そしてキックと息を合わせること。"],"eaa5dda5":["bc79c85e5597.mp3","ベースの弦は四本。E、A、D、G で、ギターの低い四本より、一オクターブ低い音だよ。"],"b032b2d7":["845fd29da55c.mp3","ベースの一番の仕事はルート。コードの名前になっている音のことだよ。C のコードなら、C を弾くの。"],"a0f538ff":["b2a3b2f2a23c.mp3","キックドラムと息を合わせよう。キックが鳴るとき、ベースもたいてい一緒に弾くの。この二つで、リズムセクションだよ。"],"457a6bc7":["f519858b2f3c.mp3","それから、動きをつけてみよう。ルートの一オクターブ上や、五度の音。同じコードでも、ぐっと弾むよ。"],"eacd028c":["ac4c8fadd311.mp3","セッションの時間だよ！私がギターとドラムを弾くから、あなたはフレットボードでベースラインを弾いてね。"],"ec0dad99":["57a8df998fab.mp3","私たちの八つの惑星を、本当の大きさの比率で。それぞれの豆知識もあるよ。"],"78f90e92":["0166c19da0c9.mp3","3Dの太陽系だよ！ドラッグで回して、ピンチでズーム。惑星をタップすると名前が聞けるよ。ぜんぶ画面に入るように、大きさと距離はぎゅっと縮めてあるの。"],"360b6aee":["63c7e84317e2.mp3","太陽のまわりを、八つの惑星が回っているの。ここでは、それぞれ本当の大きさの比率で並べているよ。"],"de7ea411":["6ca6f52959f5.mp3","水星。一番小さくて、一番太陽に近い惑星。日の出から次の日の出までの一日が、一年より長いんだよ！"],"362893e6":["827ac3543d95.mp3","金星。一番熱い惑星で、およそ465度。厚い二酸化炭素の空気が熱を閉じこめているからなの。ほかのほとんどの惑星とは逆向きに回っているよ。"],"d6bf8d96":["184c999af21a.mp3","地球。表面に液体の水があって、生命がいると分かっている、ただ一つの惑星だよ。"],"1dc571ed":["f6033b97b24e.mp3","火星。赤く見えるのは、砂ぼこりにふくまれる酸化鉄、つまりサビのせい。太陽系で知られている一番高い火山、オリンポス山があるよ。"],"fdaebf7e":["489a2d094d5f.mp3","木星。一番大きな惑星で、横に地球がおよそ十一個並ぶくらい。大赤斑は、地球より大きな嵐なんだよ。"],"5ac20b9a":["c7d700ac44a3.mp3","土星。氷と岩でできた輪で有名だよ。大きさのわりにとても軽くて、平均すると水より密度が小さいの。"],"d6d0484c":["a7501658262a.mp3","天王星。およそ98度もかたむいているから、横に寝転がったまま太陽のまわりを回っているの。"],"1bdd2f50":["a796580dc498.mp3","海王星。一番遠い惑星で、太陽系で観測された中で一番速い風が吹いているよ。およそ時速2000キロ！"],"32162ed5":["a3ff059b71ba.mp3","日本語では、五つの惑星が昔の五つの元素から名前をもらっているの。水、金、火、木、土。曜日の名前にもなっているよ！"],"1d952f30":["160399d79af6.mp3","オリオン座、北極星、そして七夕の星を、本当の位置から探してみよう。"],"e6444f54":["da5494b4ff9f.mp3","冬の夜空の主役は、狩人のオリオン。三つ並んだ星がベルトで、日本語では「三つ星」。赤いベテルギウスは昔「平家星」、白いリゲルは「源氏星」と呼ばれていたの。ライバルの二つの一族の名前だよ。"],"d0639f54":["d170435d268f.mp3","ベテルギウス、シリウス、プロキオンで、冬の大三角。シリウスは、夜空で一番明るい星だよ。"],"b213e98b":["056bc4e33238.mp3","北斗七星のひしゃくの先にある二つの星、メラクからドゥーベへ。その間の五倍くらいのばしていくと、北極星にたどり着くよ。"],"02706ad6":["28264d81a862.mp3","カシオペヤ座は、W か M の形。北極星をはさんで、北斗七星の反対側にあるの。だから片方が低いときは、もう片方が高いところにあるよ。"],"0d001339":["4def356529eb.mp3","ベガは織姫星、アルタイルは彦星。そしてデネブで、夏の大三角。七夕の伝説では、二人の恋人、ベガとアルタイルの間に天の川が流れているの。デネブは、はくちょう座にあるよ。"],"5612d4b7":["64b73dccc6f1.mp3","3Dで本物の夜空を見てみよう。明るい星はぜんぶ、本当の位置に置いてあるの。ドラッグで上も下もぐるっと見回して、星をタップすると名前が聞けるよ。"],"9a1b92aa":["56fa9e39b81e.mp3","星座は、人が思い描いた形なの。同じ星座の星でも、地球からの距離は全然違うことがあるよ。ベテルギウスの光は、届くまでに何百年もかかっているんだ。"],"f64337ac":["87159ae1c971.mp3","a二乗たすb二乗は、c二乗。どんな直角三角形でも、一番長い辺が分かる式だよ。"],"bd4506b5":["806f61807840.mp3","直角三角形には、直角の角が一つあるの。その向かいにある一番長い辺が、斜辺、c だよ。"],"4965b984":["2d3bb7114b1d.mp3","それぞれの辺に正方形を作ってみよう。数えてみて。小さな正方形9個と16個で、25個。小さい二つを合わせると、いつも大きい一つと同じになるの。"],"473adf81":["50b5c471b5fe.mp3","どうしてかな？大きな正方形の中に、同じ三角形を四つはめてみて。真ん中に残るすき間が、ちょうど c の二乗。並べ替えると、それが a の二乗たす b の二乗になるの。"],"c3985012":["9f3ec46ea84a.mp3","身近な例だよ。長さ5メートルのはしごを、壁から3メートル離して立てると、高さ4メートルまで届くの。それにテレビの大きさは対角線の長さ、つまり斜辺なんだよ！"],"46dd9800":["44c6aec08edf.mp3","日本では「三平方の定理」って呼ぶよ。自分の好きな数字でも試してみてね！"],"e80d7c8c":["b0444af2481e.mp3","貯金や投資がどうやって増えるのか。そして、早く始めるのが大事な理由。"],"df783d88":["bf8ea421db35.mp3","単利は、預けたお金にだけ利息がつくの。複利は、もらった利息にもまた利息がつく。増えた分が、また増えるんだよ。"],"c7bd85af":["32fb10a7ceaa.mp3","72の法則。72を一年の利回りで割ると、お金が二倍になるまでのだいたいの年数が分かるの。6パーセントなら、およそ12年だよ。"],"be427773":["ba80772ab2a7.mp3","少しずつでも、積み重なると大きくなるよ。毎月の金額、利回り、年数を変えて試してみてね。"],"379322be":["e76f64268ce8.mp3","投資は上がったり下がったりして、利益は決して保証されないの。手数料やインフレも大事だよ。これは計算の勉強で、投資のアドバイスではないからね。"],"ff2fb3ba":["9f045550a163.mp3","たまにたくさんやるより、毎日少しずつのほうがいい理由。"],"b6eb4a49":["935353f7a819.mp3","一日15分を一年続けると、91時間以上。長い一日なんて一度もなしで、二週間分のお仕事より多く勉強できるんだよ。"],"c3f1d0a7":["389281ff3dea.mp3","間をあけるのが効くの。覚えたことはすぐに忘れていくけど、復習するたびに忘れるスピードがゆっくりになるんだ。毎日の短い勉強が、その復習になるの。心理学では、分散効果って呼ぶよ。"],"7f6fa168":["8f5e5b8f2509.mp3","小さな成長も、複利で増えるよ。毎日1パーセントずつ良くなると、一年で約37倍。1.01の365乗は37.8だからね。素敵な計算だけど、約束じゃないよ！"],"88906b04":["84169df75963.mp3","コツは、かんたんにすること。毎日同じ時間に、小さな目標で、まだ楽しいうちにやめる。だから私のレッスンは短いんだよ！"],"9fdcc9cc":["d1906afcab9e.mp3","心臓がどこにあるか、四つの部屋、そして血液の流れ方。本物の解剖図もあるよ。"],"c6ae1d1f":["845d400ecdfc.mp3","あなたの心臓とご対面！これはかわいいイラストの模型だよ。ドラッグでぐるっと回して、それぞれの部分をタップすると名前が聞けるよ。"],"bc4003f7":["f640feaf4a22.mp3","心臓は、胸の真ん中、胸の骨のうしろ、二つの肺の間にあって、少しだけ左にかたむいているの。大きさは、だいたい自分のにぎりこぶしくらいだよ。"],"e256b730":["486e3b080008.mp3","肺が両側から心臓を包んでいるの。体の図では、その人と向かい合って見ているから、その人の左側は、あなたから見て右側になるよ。"],"1e6eb42d":["e1bba06508e4.mp3","心臓には四つの部屋があるの。上にある二つの心房が血液を集めて、下にある二つの心室が送り出す。模型でタップしてみてね！青が右側、赤が左側だよ。"],"4c19ba2d":["7d010fba7efc.mp3","右側は、酸素をもらうために血液を肺へ送るの。左側は、それを全身へ送り出すよ。"],"403c84ed":["e4402d5ca759.mp3","上にある二本の太い管が、体へ血液を運ぶ大動脈と、肺へ運ぶ肺動脈。心臓は、表面にある小さな冠動脈で、自分自身にも栄養を送っているんだよ。"],"0383c39f":["f809dcdc28a9.mp3","大人の心臓は、安静にしているとき、一分間におよそ60回から100回打つの。一日だと、およそ10万回！手首や首で脈を感じてみてね。"],"6fb71f95":["a241ec7360b4.mp3","マイクやギターを、FL Studio に録音する方法を、一歩ずつ。"],"c16c858f":["2c5a5d4a32c7.mp3","オーディオインターフェースが必要だよ。プリアンプつきのマイク入力、ギターやベース用の楽器入力、それにヘッドホンとスピーカーの出力があるの。"],"852af2cb":["1d7edf4872ac.mp3","Options の Audio settings で、Windows ならインターフェースの ASIO ドライバー、Mac ならそのデバイスを選んでね。録音するときは、128 や 256 サンプルみたいな小さいバッファにすると、遅れが少なくなるよ。"],"6fd5041f":["1ed74f97f9f9.mp3","ミキサーを開いて、空いているインサートトラックを選んでね。インサートの入力メニューで、インターフェースの入力を選ぶの。たとえば、マイクなら入力1。"],"d7214727":["d87538a8774f.mp3","インサートの録音ボタンで録音待機にして、一番大きいところがマイナス12からマイナス6 dB くらいになるようにレベルを合わせてね。赤いところまでは絶対に行かせないで。"],"4b7b2cec":["8dac25baa07c.mp3","録音ボタンを押して、プレイリストにオーディオクリップとして録音する設定を選ぶの。メトロノームとカウントインをオンにして、再生を押したら演奏スタート！"],"7d3cb60b":["4a7bd0c9169a.mp3","コツだよ。エフェクトは強くかけずに録音すること。あとから足せるからね。歌にはポップフィルターを使って、ギターは楽器入力につないで、アンプシミュレーターのプラグインはあとからかけよう。"],"113e696d":["67964df326c2.mp3","ぜんぶの音がちゃんと聞こえるように、トラックのバランスをとること。"],"7424b896":["1ffc63a8561e.mp3","楽器はそれぞれ自分のミキサーインサートに送ろう。そうすれば、楽器ごとに音量、パン、エフェクトを調整できるよ。"],"eb0df987":["81e67f7eaa6b.mp3","まずはレベルとパンから。プラグインを使う前に、フェーダーでだいたいのバランスをとってね。マスターには余裕、ヘッドルームを残しておくこと。"],"b6b89b75":["9848be572627.mp3","EQ では、Fruity Parametric EQ 2 を使って、ベースやキック以外の音の、80から100ヘルツより下の低いゴロゴロをカット。ぶつかっている周波数は、上げる前にまず削ろう。"],"cfa9e4b2":["9e46a02924c4.mp3","コンプレッサーは、大きい音と小さい音の差をならしてくれるの。だから歌がミックスの中で安定するよ。最初はやさしい設定でね。"],"646ca681":["432d04d84d3c.mp3","リバーブとディレイはセンドトラックに入れて、それぞれの楽器から少しずつ送るの。そうすると、ぜんぶの音が一つの空間にまとまるよ。"],"0ab28d6e":["58471834c890.mp3","ミックスは小さい音で、ヘッドホンでもスマホのスピーカーでも確認してね。好きな曲と聴き比べて、休憩もとること。耳は疲れるからね。"],"1bf0ab5a":["a1634db71fcc.mp3","曲をみんなに聴いてもらう前の、最後の仕上げ。"],"bacfea8f":["5498a6cae2df.mp3","マスタリングは最後のステップ。ミックス全体にやさしく EQ とコンプをかけて、マスターチェーンの一番最後にリミッターを入れるの。"],"6b44de53":["2802d61761a8.mp3","Fruity Limiter みたいなリミッターは、ピークが天井を超えないようにしてくれるの。天井はマイナス1 dB くらいにしてね。そうすれば、配信用に変換されたあとも音が割れないよ。"],"718669dd":["2675a4452788.mp3","配信サービスは、大きい曲の音量を下げて、だいたい同じ大きさにそろえるの。よくマイナス14 LUFS くらい。だから、ぎゅうぎゅうに音を大きくしても得しないんだよ。ラウドネスメーターがあると便利。"],"176f3e07":["3379466750e8.mp3","マスターは24ビットの WAV で書き出して、MP3 はそこから作ってね。公開する前に、いろんなスピーカーで聴いてみよう。"],"207802b6":["1266c026ca38.mp3","エフェクターの種類ごとの役目、よくある並べ順、そして音が聴けるボード。"],"286180fe":["784fb8e15d80.mp3","エフェクターは、ギターの音がアンプに届く前に音を変えるの。いくつかオンにして、ジャランと弾いてみて！"],"70450785":["15c721459d39.mp3","ドライブ系はざらっとした音を足すよ。オーバードライブは温かくて軽め、ディストーションは重く、ファズはワイルドでもこもこ。ディストーションをオンにして、リフを弾いてみて。"],"5a2be9b1":["5d5f3ae040dc.mp3","モジュレーション系は音を動かすの。コーラスはきらきら揺れて、トレモロは音量がふわふわ波打って、フェイザーとフランジャーはシュワーンってうねるよ。"],"76ddd0c4":["5e5a332cbab3.mp3","空間系は広がりを足すよ。ディレイは弾いた音をくり返して、リバーブは部屋やホールにいるような響きにするの。"],"3fcfd099":["d6d407c20b47.mp3","よくある順番は、チューナー、ワウ、コンプ、ドライブ、モジュレーション、ディレイ、そして最後にリバーブ。ルールは破ってもいいけど、まずはここから始めるといいよ。"],"63d6a3f1":["00efb8557c79.mp3","四分の三拍子のボックスステップ。イチ、ニ、サン、イチ、ニ、サン。"],"6f1f1390":["12bd0a395fae.mp3","ワルツは四分の三拍子。イチ、ニ、サン、イチ、ニ、サン、と数えて、イチで少しだけ体重をのせるの。"],"50d16af0":["d8954b34145a.mp3","カウント1。左足を前に出すよ。"],"a7453e71":["d951a861fc29.mp3","カウント2。右足を横へ、少しだけ前に出すよ。"],"7fb70994":["4921acf54ce3.mp3","カウント3。左足を右足の横にそろえる。これで箱の半分！"],"c8d7d37f":["ed74d746a623.mp3","もう一度カウント1。右足を後ろへ。カウント2、左足を横へ。カウント3、右足をそろえる。床に四角が描けたね！"],"5669554a":["8671a74e5f6c.mp3","再生を押して、一緒にステップしてみよう。四角がくるくる続くよ。背すじをのばして、腕で形を作って、カウント2と3で少しだけ伸び上がるの。パートナーは鏡みたいに、右足を後ろに引くところから始めるよ。"],"c930cb97":["105253e845ea.mp3","小切手の一つ一つの欄、そして安全に使う方法。"],"f3031498":["c1e3abf388d5.mp3","これはアメリカ式の小切手の見本だよ。どの部分も大事。一つずつ見ていこう。"],"1bac5b5e":["4f409ae4640b.mp3","右上に、今日の日付を書くよ。"],"cee9fe1b":["be3764824918.mp3","Pay to the order of のあとに、お金を受け取る人の名前を正確に書くの。個人の名前か、会社の名前だよ。"],"8b18d796":["27e104ebd785.mp3","四角い枠には、金額を数字で書くよ。ドルの記号のすぐ横から書き始めて、あとから何も書き足せないようにするの。"],"80fceb45":["e078915d5026.mp3","長い線には、金額を英語の言葉で書くよ。セントは100分のいくつ、と分数で。書き終わったら、余白に線を引いてうめてね。数字と言葉が合わないときは、言葉のほうが正式な金額になるんだよ。"],"c8649837":["27997c28ffda.mp3","メモの欄は書いても書かなくてもいいの。請求書の番号みたいな、自分用のメモだよ。最後に、銀行に登録しているのと同じサインをしてね。"],"37eecbef":["462fa61af916.mp3","下にある数字は、銀行のルーティング番号、あなたの口座番号、そして小切手の番号。何も書いていない小切手には絶対にサインしないで、いつもペンで書いて、書き間違えたら VOID と大きく書いてね。"],"54585999":["43d2ea547b61.mp3","日本では、個人で小切手を使うことはほとんどないの。みんな「振込」を使うよ。「小切手」は、ほとんど会社で使うものなんだ。"],"b1f788f9":["2f38c3db9d37.mp3","どれくらい体を動かせばいいか、安全なウォームアップ、そして私と一緒にやる6ラウンドのタイマー。"],"d23d78f9":["83b8edf4ff4b.mp3","世界保健機関、WHO によると、大人は一週間に150分から300分、早歩きくらいの運動をして、さらに週2日以上は筋トレをするのがおすすめなの。子どもは一日に一時間くらいだよ。"],"4f5b68c5":["9b027071a4ba.mp3","まずは5分から10分、ウォームアップしよう。足踏みして、腕を振って、肩を回して、筋肉の準備をしてね。"],"3f8665f2":["5fd913d1571b.mp3","速さより、正しいフォームが大事だよ。スクワットではひざをつま先と同じ向きにして、背中はまっすぐ。腕立て伏せは、頭からかかとまで一直線に。壁やひざをついた腕立てから始めるのもいいよ。"],"58b4e9f5":["ce7b9342ac96.mp3","胸の痛み、めまい、するどい痛みを感じたらすぐにやめてね。持病がある人は、始める前にお医者さんに相談しよう。"],"0ba6cc29":["6b2e001ec1b7.mp3","準備はいい？六つの動きを、それぞれ30秒、休憩は15秒。私がカウントするからね！"],"8a05ca69":["a9bc65c0621d.mp3","ガーリックバターパスタを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"fede41cc":["f1beca3224d0.mp3","かんたん野菜炒めを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"b47a5822":["fc12493c1bc1.mp3","トマトと卵の炒めものを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"29fe5be0":["4adfbd8bdd41.mp3","基本のパンケーキを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"adc0779b":["5106f70af631.mp3","かんたんチャーハンを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"4a81736d":["839dbe12e0fe.mp3","天板で焼くロースト野菜を作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"92c9446c":["7882c8c3166c.mp3","お味噌汁を作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"e04502da":["92d6237f84a9.mp3","小さなお鍋に水とだしの素を入れて、ふつふつするくらいに温めてね。"],"f630cd1e":["9f222a70ba8c.mp3","乾燥わかめを入れるよ。一、二分でふくらむからね。"],"c3a9dca7":["89cdd3b8718b.mp3","さいの目に切った豆腐をそっと入れて、一分くらい温めよう。"],"21b7588c":["25fee0974aac.mp3","火を弱くしてね。お玉に味噌をのせて、お汁にひたしながら溶かして、全体に混ぜるの。味噌を入れたあとは沸騰させないでね。煮立たせると風味が飛んじゃうから。"],"8a467106":["eb7ff3f2e344.mp3","すぐにお椀によそって、ねぎをのせてできあがり！"],"d20e02b3":["178bc796a65e.mp3","チキンと野菜のスープを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"f418e347":["51fefc35be09.mp3","大きなお鍋に油を入れて中火で温めて、玉ねぎ、にんじん、セロリを5分くらい炒めて、しんなりさせてね。"],"34a1f08d":["c95539dae5ef.mp3","にんにくを入れて、30秒くらい混ぜるよ。"],"1fca7977":["b2493168af9b.mp3","鶏肉、スープストック、じゃがいも、タイムを入れて、沸騰したら火を弱めて、ふたをして20分から25分煮込もう。"],"22023156":["4758113f8e46.mp3","鶏肉を取り出してね。真ん中が74度になっていれば火が通ってるよ。フォーク二本でほぐして、お鍋に戻してね。"],"af023d2f":["eec31acec808.mp3","塩とこしょうで味をととのえて、皮がパリッとしたパンと一緒にどうぞ。"],"bf9ffda0":["3ff359edfc26.mp3","どら焼きを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"d3a1d207":["b238c6c1d2c6.mp3","卵、砂糖、はちみつを、白っぽくなめらかになるまで泡立ててね。"],"612a99de":["ecb0902688fd.mp3","小麦粉とベーキングパウダーをふるい入れて、粉っぽさがなくなるまでさっくり混ぜるの。生地は15分休ませてね。"],"c1751bc8":["9c6200aa1047.mp3","水をスプーン一杯ずつ加えて混ぜて、とろっとしたクリームみたいにゆっくり流れるくらいにしてね。"],"840a3dfe":["7d08d0329806.mp3","フッ素加工のフライパンに油を薄くひいて、弱めの中火で温めるよ。一枚につき大さじ3杯くらいの生地を流して、表面にぷつぷつ泡が出てきたら、だいたい2分くらいね、ひっくり返してもう30秒焼こう。"],"c5c7e634":["67628e25c477.mp3","焼けた生地は、きれいなふきんをかけて冷ますと、しっとりやわらかいままだよ。一枚にあんこをぬって、もう一枚を重ねたらできあがり。召し上がれ！"],"0e4dd75f":["3fef0cec2b21.mp3","白玉団子を作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"7db3b78d":["bd88c50a8e3c.mp3","白玉粉をボウルに入れて、水を少しずつ加えながらこねてね。耳たぶくらいのやわらかさになったらオーケー。これが日本の昔ながらの目安だよ。"],"dee57101":["ca6d24fa24c3.mp3","直径2センチくらいに丸めて、真ん中を少しへこませてね。そうすると、均一にゆであがるよ。"],"15ad59cd":["e6d6b76482ad.mp3","沸騰したお湯に入れてね。浮かんできたら、さらに1、2分ゆでよう。"],"7663b6f8":["1aff0d987141.mp3","氷水を入れたボウルにすくって、冷やしてきゅっとさせたら、水気を切ってね。"],"2e6c0c20":["b61fb9c25ca1.mp3","きなこ砂糖やあんこをかけて召し上がれ。もちもちしているから、小さい子やお年寄りには小さく切って、よくかんで食べてね。"],"cf5d64e0":["27da2abc65d8.mp3","いちごパフェを作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"ca3fbad1":["0b20085a0bd8.mp3","ミートボールのトマト煮を作ろう！まずは材料をぜんぶそろえてね。出したものから一つずつチェックしていこう。"],"ff5fdc20":["973866bc06c2.mp3","お客さんを紹介するね。マリアさんは小さな金物屋さんを経営していて、15年間ずっと紙の帳簿を使っているの。テクノロジーが嫌いなわけじゃないけど、「時間の節約」になるはずの道具が、逆に時間を食うのを何度も見てきたんだ。"],"e1774362":["ce05052001e4.mp3","マリアさんが本当に疑っているのは、投資に見合う効果、ROI があるかどうか。それに、自分と二人の従業員が使い方を覚えられるかも心配なの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"52f3749e":["7ff743015d1d.mp3","機能の一覧から始めないで、今本当に困っていることから話そう。売り込む前に、紙の帳簿で何がうまくいかないのか聞いてみてね。"],"291e012a":["0d2e91a6ebbb.mp3","リスクなしで本当に試せる方法を提案しよう。あいまいな約束じゃなくて、お店がひまな週にお試しする、とかね。"],"c942aac3":["9e14d677ae44.mp3","覚えるのが大変、という不安から逃げずに、まっすぐ向き合おう。「かんたんですよ」と言うだけじゃなくて、準備がどれだけ少ないかを実際に見せてね。"],"dd5367e9":["55ea7a1f312e.mp3","お客さんを紹介するね。デイビッドさんは中規模の会計事務所のオフィスマネージャー。ライバル会社との二年契約が始まって、八か月たったところ。満足はしていないけど、乗りかえるのは面倒だと感じているの。"],"0e450ed7":["0694bd78e678.mp3","デイビッドさんは、身動きがとれないと感じているの。解約金や、乗りかえ中にサービスが止まることが心配なんだ。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"c663c8b1":["1d61c589b588.mp3","今のサービスの、具体的にどこが不満なのか聞いてみよう。ありきたりな売り込みより、そこが本当のカギになるよ。"],"7cdd1870":["afe7ee815ac9.mp3","乗りかえのコストに正面から向き合おう。解約金の分を埋め合わせできるか、それとも契約が終わるときのために今の価格で予約できるか。"],"f79d4854":["168f9bdff792.mp3","移行が具体的にどう進むのか、実際どれくらいしか止まらないのかを説明して、リスクの不安を小さくしよう。"],"e9baf4ca":["d89c6ade0c92.mp3","お客さんを紹介するね。トムさんは、同じコードつき掃除機を十二年使っているの。重いし、コードはじゃまだけど、ゴミはちゃんと吸ってくれるんだ。"],"5843de91":["24190b7bf5ec.mp3","トムさんは、わざわざ解決するほどの問題だと思っていなくて、値段にも敏感なの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"1d16f937":["bb1199300663.mp3","「その掃除機はダメですよ」と言い争わないで。コードの長さとか、二階に運ぶときとか、困る瞬間を具体的に聞いて、トムさん自身に気づいてもらおう。"],"e5cec626":["7c15c93e750a.mp3","紙の上で性能を説明するより、軽さや動かしやすさを実際に見せるほうがずっと伝わるよ。"],"a169fb0e":["5c36e1e2d04a.mp3","値段の話になったら、「すぐに元が取れますよ」みたいな決まり文句じゃなくて、トムさんが実際にどれくらい使うかと比べてみてね。"],"0720c068":["dda580dacc3d.mp3","お客さんを紹介するね。プリヤさんはデモで商品を気に入ってくれたけど、次の四半期まで予算の承認が止まっているんだって。"],"8861edef":["f1cc0f893838.mp3","プリヤさんは、本当に予算が足りないだけで、興味がないわけじゃないの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"],"e2ac8f52":["ac75f070aa33.mp3","今ある小さな予算に収まる、もっと小さなプランや、お試しの導入がないか聞いてみよう。"],"5d2024e8":["336959bf0e5e.mp3","予算がいつ再開するのかをはっきり聞いて、開始は後でも、今日の価格で予約できると提案しよう。"],"ac2943e4":["2f011d73c2e4.mp3","ジョーダンさんは、値段の話より前に、まず信頼が必要なの。これが本当の反論だよ。あなたの仕事は、そこをかわすんじゃなくて、ちゃんと答えること。"]};
